<script setup lang="ts">
import { PhArrowLeft, PhCurrencyInr, PhPlus, PhStethoscope, PhUsersThree } from '@phosphor-icons/vue'
import { useReferrals } from '~/composables/referrals/useReferrals'
import { formatReferralDate, formatReferralMoney } from '~/utils/referrals'
import { usePatients } from '~/composables/patients/usePatients'
import { normalizeApiError } from '~/utils/api/errors'
definePageMeta({ layout: 'tenant', middleware: ['tenant-auth', 'tenant-approval'] })
const route = useRoute(); const id = computed(() => String(route.params.id)); const { detail, loading, error, loadDetail, logReferral } = useReferrals(); const { patients, load: loadPatients } = usePatients(); const tab = ref<'overview' | 'referrals'>('overview'); const modalOpen = ref(false); const saving = ref(false); const actionError = ref(''); const form = reactive({ patient_id: '', revenue: '', notes: '' })
const doctor = computed(() => detail.value?.doctor); const referralData = computed(() => detail.value || { doctor: undefined, referrals: [], patients_referred: 0, total_revenue: 0 }); const needsReconnect = computed(() => { if (!doctor.value?.last_contact_at) return true; return (Date.now() - new Date(doctor.value.last_contact_at).getTime()) / 86400000 >= Number(doctor.value.reconnect_every_days || 30) })
const saveReferral = async () => { if (!form.patient_id) { actionError.value = 'Select a patient.'; return }; saving.value = true; actionError.value = ''; try { await logReferral(id.value, { patient_id: form.patient_id, revenue: Number(form.revenue || 0), notes: form.notes }); modalOpen.value = false; Object.assign(form, { patient_id: '', revenue: '', notes: '' }) } catch (cause) { actionError.value = normalizeApiError(cause, 'Referral could not be logged.') } finally { saving.value = false } }
onMounted(async () => { await Promise.all([loadDetail(id.value), loadPatients()]) })
watch(id, value => loadDetail(value)); watch(doctor, value => { if (value) useHead({ title: String(value.name) }) }, { immediate: true })
</script>
<template>
  <section class="referral-detail-page"><NuxtLink to="/doctors" class="referral-back-link"><PhArrowLeft :size="16" /> Referral CRM</NuxtLink><div v-if="loading && !doctor" class="referral-state">Loading referrer…</div><div v-else-if="error" class="referral-state"><p>{{ error }}</p><button type="button" class="referral-secondary-button" @click="loadDetail(id)">Try again</button></div><template v-else-if="doctor"><section class="referral-profile-card"><div class="referral-profile-icon"><PhStethoscope :size="30" /></div><div class="referral-profile-copy"><p class="referral-eyebrow">Referring doctor</p><h2>{{ doctor.name }}</h2><p>{{ doctor.specialty || 'Specialty not recorded' }} · {{ doctor.clinic || 'Clinic not recorded' }}</p></div><span class="referral-status" :class="{ reconnect: needsReconnect }">{{ needsReconnect ? 'Needs reconnect' : 'Recently contacted' }}</span></section><nav class="referral-tabs"><button type="button" :class="{ active: tab === 'overview' }" @click="tab = 'overview'">Overview</button><button type="button" :class="{ active: tab === 'referrals' }" @click="tab = 'referrals'">Referrals ({{ referralData.referrals?.length || 0 }})</button></nav><div v-if="tab === 'overview'" class="referral-detail-grid"><article class="referral-info-card"><h3>Contact details</h3><dl><div><dt>Clinic</dt><dd>{{ doctor.clinic || '—' }}</dd></div><div><dt>Category</dt><dd>{{ String(doctor.category || '—').replace(/_/g, ' ') }}</dd></div><div><dt>Phone</dt><dd>{{ doctor.phone || '—' }}</dd></div><div><dt>Email</dt><dd>{{ doctor.email || '—' }}</dd></div><div><dt>Reconnect every</dt><dd>{{ doctor.reconnect_every_days || 30 }} days</dd></div><div><dt>Last contact</dt><dd>{{ formatReferralDate(doctor.last_contact_at) }}</dd></div></dl></article><div class="referral-stat-grid"><article><span><PhUsersThree :size="19" /></span><small>Patients referred</small><strong>{{ referralData.patients_referred || 0 }}</strong></article><article><span><PhCurrencyInr :size="19" /></span><small>Revenue generated</small><strong>{{ formatReferralMoney(referralData.total_revenue) }}</strong></article></div></div><article v-else class="referral-history-card"><header><div><h3>Referral history</h3><p>Patients referred by this doctor.</p></div><button type="button" class="referral-primary-button" @click="actionError = ''; modalOpen = true"><PhPlus :size="16" /> Log referral</button></header><p v-if="actionError" class="referral-form-error">{{ actionError }}</p><div v-if="!referralData.referrals?.length" class="referral-history-empty">No referrals yet.</div><NuxtLink v-for="item in referralData.referrals" :key="item.id" :to="item.patient_id ? `/patients/${item.patient_id}` : '/patients'" class="referral-history-row"><div><strong>{{ item.patient_name || 'Unknown patient' }}</strong><small>{{ formatReferralDate(item.created_at) }} · {{ item.notes || 'No notes' }}</small></div><b>{{ formatReferralMoney(item.revenue) }}</b></NuxtLink></article></template><div v-if="modalOpen" class="referral-modal" role="dialog" aria-modal="true"><button type="button" class="referral-modal-backdrop" aria-label="Close" @click="modalOpen = false" /><section class="referral-modal-panel"><header><div><p class="referral-eyebrow">Referral history</p><h2>Log patient referral</h2></div></header><form @submit.prevent="saveReferral"><label>Patient *<select v-model="form.patient_id" required><option value="">Select patient</option><option v-for="patient in patients" :key="patient.id" :value="patient.id">{{ patient.name }}{{ patient.phone ? ` (${patient.phone})` : '' }}</option></select></label><label>Revenue (₹)<input v-model="form.revenue" type="number" min="0" /></label><label>Notes<textarea v-model="form.notes" rows="3" /></label><footer><button type="button" class="referral-secondary-button" @click="modalOpen = false">Cancel</button><button type="submit" class="referral-primary-button" :disabled="saving">{{ saving ? 'Saving…' : 'Save referral' }}</button></footer></form></section></div></section>
</template>
